{
  "actions": [
    {
      "action": "Rotate uncertain diagnoses through bounded work turns",
      "mechanism": "A review limit prevents one uncertain item from monopolizing a bench while waiting jobs repeatedly lose access.",
      "implementation": "Set 15-minute diagnostic reviews, not completion promises. At safe stopping points, rotate to an unassessed item; prioritize one apparently short, safe job, then the oldest waiting job.",
      "check": "Log bench turns; flag any eligible item bypassed for two rotations and any review overrun without a safety reason.",
      "risk": "Stopping and restarting adds overhead; never force an unsafe pause."
    },
    {
      "action": "Separate intake screening from electrical bench access",
      "mechanism": "Exterior-only intake lets volunteers establish ownership and routing without consuming specialist attention or opening electrical equipment.",
      "implementation": "Assign one existing volunteer to record symptoms, electrical status, owner receipt number, and location. Queue electrical opening exclusively for the specialist; route uncertain classifications there too.",
      "check": "Audit every electrical opening for specialist involvement and every accepted item for a matching receipt and recorded location.",
      "risk": "Screening must not drift into electrical opening or testing."
    },
    {
      "action": "Move parts-blocked items into explicit waiting status",
      "mechanism": "A separate status and off-bench location distinguish blocked inventory from actionable work without adding workbenches.",
      "implementation": "Mark items WAITING FOR PART, recording the missing part, sourcing responsibility, and next review date. Move safely secured items to labeled existing storage; update the receipt-linked location.",
      "check": "At shift end, verify each parts-blocked item has a location and sourcing owner; investigate any still occupying a bench.",
      "risk": "If safe storage is unavailable, arrange owner collection instead."
    },
    {
      "action": "Require accepted responsibility at every shift handoff",
      "mechanism": "Receipt-linked history preserves prior decisions while explicit acceptance prevents responsibility disappearing between shifts.",
      "implementation": "Append dated notes recording volunteer, status, location, next action, and blocker. Incoming volunteers acknowledge assigned items; specialist-only actions remain restricted. Promise completion only with an explicit uncertainty range; otherwise report status.",
      "check": "Before departure, outgoing volunteers reconcile every retained item against the log and confirm an incoming responsible person has accepted it.",
      "risk": "Unaccepted items must remain visibly unresolved, not marked handed over."
    }
  ],
  "abstention_reason": ""
}
